import{_ as a,o as s,c as n,a5 as t}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"22. Pointers and Addresses","description":"The Little Book of C — 22. Pointers and Addresses","frontmatter":{"title":"22. Pointers and Addresses","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Working with Memory"],"description":"The Little Book of C — 22. Pointers and Addresses","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":22,"sidebarWeight":22,"lang":"en-US","alternateEn":"/posts/c教程/en-US/03-Working with Memory/022-Pointers and Addresses","alternateZh":"/posts/c教程/zh-CN/03-内存/022-Pointers and Addresses"},"headers":[],"relativePath":"posts/c教程/en-US/03-Working with Memory/022-Pointers and Addresses.md","filePath":"posts/c教程/en-US/03-Working with Memory/022-Pointers and Addresses.md","lastUpdated":1790163617000}'),o={name:"posts/c教程/en-US/03-Working with Memory/022-Pointers and Addresses.md"};function i(r,e,p,d,l,c){return s(),n("div",null,[...e[0]||(e[0]=[t(`<p>[中文版本](/posts/c教程/zh-CN/03-内存/022-Pointers and Addresses)</p><p>Pointers are at the heart of C programming. They give you direct access to memory, the power to read, write, and manipulate data stored anywhere in your program. Understanding pointers transforms how you think about variables, functions, and data structures.</p><p>You can’t truly master C without mastering pointers.</p><h4 id="what-is-a-pointer" tabindex="-1">What Is a Pointer? <a class="header-anchor" href="#what-is-a-pointer" aria-label="Permalink to &quot;What Is a Pointer?&quot;">​</a></h4><p>A pointer is a variable that stores the address of another variable. Think of it as a reference to a specific spot in memory.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int value = 42;</span></span>
<span class="line"><span>int *ptr = &amp;value; // pointer to int, stores the address of value</span></span></code></pre></div><ul><li><code>&amp;value</code> gives the memory address of<code>value</code>.</li><li><code>ptr</code> holds that address.</li><li><code>*ptr</code> lets you access the value stored there (this is called dereferencing).</li></ul><h4 id="tiny-code" tabindex="-1">Tiny Code <a class="header-anchor" href="#tiny-code" aria-label="Permalink to &quot;Tiny Code&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int number = 10;</span></span>
<span class="line"><span>    int *p = &amp;number;  // pointer stores address of number</span></span>
<span class="line"><span>    printf(&quot;Value of number: %d\\n&quot;, number);</span></span>
<span class="line"><span>    printf(&quot;Address of number: %p\\n&quot;, (void *)&amp;number);</span></span>
<span class="line"><span>    printf(&quot;Pointer p holds address: %p\\n&quot;, (void *)p);</span></span>
<span class="line"><span>    printf(&quot;Value through pointer: %d\\n&quot;, *p);</span></span>
<span class="line"><span>    *p = 20;</span><span>  // modify the value via the pointer</span></span>
<span class="line"><span>    printf(&quot;New value of number: %d\\n&quot;, number);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Compile and run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc pointer_basics.c -o pointer_basics</span></span>
<span class="line"><span>./pointer_basics</span></span></code></pre></div><p>Output (addresses vary):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Value of number: 10</span></span>
<span class="line"><span>Address of number: 0x7ffc8f4c9c4c</span></span>
<span class="line"><span>Pointer p holds address: 0x7ffc8f4c9c4c</span></span>
<span class="line"><span>Value through pointer: 10</span></span>
<span class="line"><span>New value of number: 20</span></span></code></pre></div><h4 id="pointer-declaration-and-dereferencing" tabindex="-1">Pointer Declaration and Dereferencing <a class="header-anchor" href="#pointer-declaration-and-dereferencing" aria-label="Permalink to &quot;Pointer Declaration and Dereferencing&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Syntax</th><th>Meaning</th></tr></thead><tbody><tr><td><code>int *p;</code></td><td>Pointer to an integer</td></tr><tr><td><code>char *c;</code></td><td>Pointer to a character</td></tr><tr><td><code>float *f;</code></td><td>Pointer to a float</td></tr><tr><td><code>p = &amp;x;</code></td><td>Assigns address of variable<code>x</code> to pointer<code>p</code></td></tr><tr><td><code>*p</code></td><td>Accesses (dereferences) the value stored at the address held by<code>p</code></td></tr></tbody></table><p>Dereferencing works both ways:</p><ul><li>Reading the value:<code>x = *p;</code></li><li>Writing to the address:<code>*p = 99;</code></li></ul><h4 id="null-pointers" tabindex="-1">Null Pointers <a class="header-anchor" href="#null-pointers" aria-label="Permalink to &quot;Null Pointers&quot;">​</a></h4><p>A pointer that points to nothing should be set to<code>NULL</code>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int *ptr = NULL;</span></span>
<span class="line"><span>if (ptr == NULL) {</span></span>
<span class="line"><span>    printf(&quot;Pointer is not initialized.\\n&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Dereferencing a null pointer (<code>*ptr</code> when<code>ptr == NULL</code>) causes a segmentation fault, one of the most common C errors.</p><h4 id="pointer-to-pointer" tabindex="-1">Pointer to Pointer <a class="header-anchor" href="#pointer-to-pointer" aria-label="Permalink to &quot;Pointer to Pointer&quot;">​</a></h4><p>You can have pointers that store addresses of other pointers.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int x = 5;</span></span>
<span class="line"><span>int *p = &amp;x;</span></span>
<span class="line"><span>int **pp = &amp;p;</span></span>
<span class="line"><span>printf(&quot;x = %d\\n&quot;, **pp);</span></span></code></pre></div><p>This concept appears in multi-dimensional arrays and function pointers.</p><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>Pointers are what make C powerful:</p><ul><li>They enable dynamic memory allocation (<code>malloc</code>,<code>calloc</code>,<code>free</code>).</li><li>They allow arrays, strings, and structures to be passed efficiently.</li><li>They are the foundation for linked lists, trees, and system calls.</li></ul><p>But they also demand precision. A single misused pointer can cause crashes or memory corruption.</p><p>Mastering pointers means mastering both control and responsibility over memory.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><ol><li>Write a program that declares an integer and prints both its value and address.</li><li>Create a pointer to that integer and modify the variable’s value through the pointer.</li><li>Try declaring<code>int *p = NULL;</code> and check it before dereferencing.</li><li>Print a pointer to a pointer (<code>int **</code>) and see how the addresses relate.</li><li>For fun, declare two variables and make one pointer swap their values using dereferencing.</li></ol><p>Once you truly understand pointers, the rest of C, arrays, structs, dynamic memory, even function calls, begins to make sense. They are the bridge between your code and the machine’s actual memory.</p>`,33)])])}const m=a(o,[["render",i]]);export{u as __pageData,m as default};
